"use client";
import { useEffect, useRef } from "react";

// Extracted verbatim from the original single-file game (noir-slice.html).
// Kept as raw HTML/CSS strings rather than hand-converted JSX so none of the
// game's hundreds of getElementById() lookups can silently break.
const MARKUP_HTML = "\n<canvas id=\"c\"></canvas>\n\n<div id=\"hud\">\n  <div id=\"objective\"><span class=\"tag\">OBJECTIVE</span><br><b id=\"objText\"></b></div>\n  <div id=\"toast\"></div>\n  <div id=\"dbgHud\"></div>\n  <div class=\"overlay\" id=\"elevOverlay\">\n    <div style=\"background:#101318;border:1px solid #3a4450;padding:26px 34px;text-align:center\">\n      <div style=\"color:#7a92a8;letter-spacing:3px;font-size:12px;margin-bottom:14px\">ELEVATOR \u00b7 SELECT FLOOR</div>\n      <div id=\"elevBtns\"></div>\n      <div style=\"margin-top:14px\"><button id=\"elevClose\" style=\"background:#141a20;border:1px solid #3a4450;color:#c8d0d8;padding:6px 16px;cursor:pointer;font:12px 'Courier New'\">STAY</button></div>\n    </div>\n  </div>\n  <div class=\"overlay\" id=\"choiceOverlay\">\n    <div style=\"background:rgba(8,10,13,.96);border:1px solid #3a4450;padding:30px 38px;text-align:center;max-width:520px\">\n      <div id=\"choiceText\" style=\"color:#c8d0d8;font:15px Georgia,serif;line-height:1.7;margin-bottom:22px\"></div>\n      <button id=\"choiceA\" style=\"display:block;width:100%;margin:8px 0;background:#141a20;border:1px solid #3a4450;color:#e8b060;padding:10px;cursor:pointer;font:13px 'Courier New';letter-spacing:1px\"></button>\n      <button id=\"choiceB\" style=\"display:block;width:100%;margin:8px 0;background:#141a20;border:1px solid #3a4450;color:#c8d0d8;padding:10px;cursor:pointer;font:13px 'Courier New';letter-spacing:1px\"></button>\n    </div>\n  </div>\n  <div id=\"dbgToggle\" title=\"Open debug menu (also ` or F1)\">DEBUG \u2630</div>\n  <div id=\"menuToggle\" title=\"Save / Load (Esc)\">MENU \u23f8</div>\n  <div id=\"dbgPanel\">\n    <h3>DEBUG \u00b7 NOIR SLICE <span style=\"float:right;color:#54606c;font-size:10px\">[`] close</span></h3>\n    <h4>PLAYER</h4>\n    <button id=\"dbNoclip\">Noclip: OFF</button>\n    <button id=\"dbHud\">HUD: OFF</button>\n    <label>Speed \u00d7<span id=\"dbSpdV\">1.0</span><input type=\"range\" id=\"dbSpd\" min=\"0.5\" max=\"4\" step=\"0.1\" value=\"1\"></label>\n    <label><button id=\"dbBatt\">Refill battery</button><button id=\"dbInfBatt\">\u221e Battery: OFF</button></label>\n    <h4>TELEPORT</h4>\n    <button data-tpz=\"arrival,911,4.4,1.5708\">Arrival</button>\n    <button data-tpz=\"street,-96,26,0\">Street</button>\n    <button data-tpz=\"dream1,100,20,0\">Dream 1</button>\n    <button data-tpz=\"floor8,2.35,5.55,-1.34\">8001 chair</button>\n    <button data-tpz=\"floor8,7.4,1.1,3.14\">Door 8004</button>\n    <button data-tpz=\"floor8,16.5,1.1,3.14\">Door 8007</button>\n    <button data-tpz=\"floor8,11.3,5.5,1.57\">8007 kitchen</button>\n    <button data-tpz=\"lobbyG,205,3,3.14\">Ground lobby</button>\n    <button data-tpz=\"alley,302,3,-1.57\">Alley</button>\n    <button data-tpz=\"restock,405,4,3.14\">Restock room</button>\n    <button data-tpz=\"dream2,502,44,0\">Chase dream</button>\n    <button data-tpz=\"floor21,606,1.1,-1.57\">21st floor</button>\n    <button data-tpz=\"terrace,704,7,-1.57\">Terrace</button>\n    <button data-tpz=\"metro,803,3,-1.57\">Metro</button>\n    <h4>FLOW / STORY</h4>\n    <button id=\"dbSkip\">Skip intro (wake in 8001)</button>\n    <button id=\"dbOpen7\">Open 8007</button>\n    <button id=\"dbSolve\">Solve Puzzle 1</button>\n    <button id=\"dbGen\">Generator \u2192 chase</button>\n    <button id=\"dbBoxes\">Solve box room</button>\n    <button id=\"dbMusic\">Solve music box</button>\n    <button id=\"dbLedge\">Show ledge</button>\n    <button id=\"dbEndB\">Ending B setup (photo+pieces)</button>\n    <button id=\"dbFigure\">Spawn Figure</button>\n    <button id=\"dbFinish\">Credits</button>\n    <h4>GIVE</h4>\n    <button id=\"dbNotes\">All journal notes</button>\n    <button id=\"dbItems\">Piece #1 + Key</button>\n    <h4>ATMOSPHERE</h4>\n    <label>Dread <span id=\"dbDreadV\">0.00</span><input type=\"range\" id=\"dbDread\" min=\"0\" max=\"1\" step=\"0.01\" value=\"0\"></label>\n    <button id=\"dbFreeze\">Freeze dread: OFF</button>\n    <button id=\"dbBright\">Fullbright: OFF</button>\n    <button id=\"dbRaw\">PS2 FX: ON</button>\n    <button id=\"dbCol\">Colliders: OFF</button>\n  </div>\n  <div id=\"reticle\"></div>\n  <div id=\"prompt\"><kbd>E</kbd><span id=\"promptText\"></span></div>\n  <div id=\"subtitle\"></div>\n  <div id=\"battery\"><div class=\"lbl\">FLASHLIGHT \u00b7 F</div><div class=\"bar\"><div class=\"fill\" id=\"battFill\"></div></div></div>\n  <div id=\"inv\"></div>\n  <div id=\"journalHint\">TAB \u00b7 JOURNAL</div>\n</div>\n\n<div class=\"overlay\" id=\"noteOverlay\"><div class=\"paper\"><div class=\"close\" onclick=\"closeNote()\">[E] CLOSE</div><h3 id=\"noteTitle\"></h3><div id=\"noteBody\"></div></div></div>\n\n<div class=\"overlay\" id=\"dialOverlay\"><div id=\"dialBox\">\n  <h3>EILEEN'S LANDLINE</h3>\n  <div id=\"dialDisp\">&nbsp;</div>\n  <div id=\"dialPad\"></div>\n  <div id=\"dialRow\"><button class=\"dbtn\" id=\"dialClear\">CLEAR</button><button class=\"dbtn\" id=\"dialCall\">CALL</button><button class=\"dbtn\" id=\"dialHang\">HANG UP</button></div>\n</div></div>\n\n<div class=\"overlay\" id=\"journalOverlay\"><div id=\"journalBox\">\n  <div style=\"display:flex;flex-direction:column;width:220px\"><div id=\"jHead\">THOMAS REED \u2014 JOURNAL</div><div id=\"jList\" style=\"flex:1\"></div></div>\n  <div id=\"jRead\">\u2026</div>\n</div></div>\n\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 LANDING \u00b7 CASE FILE FRONT PAGE \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div id=\"landing\" style=\"--ldhero:url(data:image/jpeg;base64,)\">\n  <div class=\"ldGrain\"></div>\n  <div class=\"ldRec\"><span class=\"d\"></span>REC</div>\n  <div class=\"ldHero\"><div class=\"ldIn\">\n    <div class=\"ldCase\">CASE FILE NO. <b>8007</b> \u2014 STATUS: <b>UNSOLVED</b></div>\n    <div class=\"ldWord\">NOIR</div>\n    <div class=\"ldSub\">\"T R A N S I T\"</div>\n    <p class=\"ldLog\">A man returns, one year later, to search a rain-soaked apartment building for his missing wife \u2014 <b>solving the puzzles of his own grief</b> before the last train leaves without him.</p>\n    <div class=\"ldBtns\">\n      <span class=\"ldBtn\" id=\"ldPlay1\">\u25b6 PLAY \u2014 FREE, IN THIS TAB</span>\n      <span class=\"ldBtn\" id=\"ldContinue\" style=\"display:none\">\u21bb CONTINUE \u2014 LOAD SAVE</span>\n      <span class=\"ldBtn ghost\" id=\"ldMore\">READ THE FILE \u2193</span>\n    </div>\n  </div></div>\n  <div class=\"ldSec\" id=\"ldFile\"><div class=\"ldIn\">\n    <div class=\"ldEyebrow\">EXHIBIT A \u2014 TRANSCRIPT</div>\n    <div class=\"ldTyped\">\n      <p><b>Eleven-forty.</b> The last train lets him out into a station the colour of an old bruise. Nobody else gets off. Thomas Reed is walking back into <b>Haldane Court</b> for the first time since <span class=\"ldRedact\">\u2588\u2588\u2588\u2588\u2588\u2588\u2588\u2588</span>.</p>\n      <p>It has been <b>one year since Eileen</b>. The building remembers her better than the police report did. Notes turn up where she would have left them. A music box wants an order only she would know. <b>There are two ways down from the roof.</b> Only one of them is a way out.</p>\n    </div>\n    <div class=\"ldStats\">\n      <div>RUNTIME<b>~35\u201350 MIN</b></div><div>FORMAT<b>ONE .HTML FILE</b></div>\n      <div>RENDER<b>320\u00d7240 \u00b7 DITHERED</b></div><div>ENDINGS<b>TWO</b></div><div>PRICE<b>FREE</b></div>\n    </div>\n  </div></div>\n  <div class=\"ldSec\"><div class=\"ldIn\">\n    <div class=\"ldEyebrow\">EXHIBIT B \u2014 SCENE PHOTOGRAPHS</div>\n    <div class=\"ldBoard\">\n      <div class=\"ldPol\" style=\"--r:-2.5deg\"><div class=\"pin\"></div><img alt=\"Transit platform at night\" src=\"data:image/jpeg;base64,\"><div class=\"tag\"><b>EXHIBIT B-1</b>Transit platform \u2014 23:40</div></div>\n      <div class=\"ldPol\" style=\"--r:2deg\"><div class=\"pin\"></div><img alt=\"8th floor corridor\" src=\"data:image/jpeg;base64,\"><div class=\"tag\"><b>EXHIBIT B-2</b>8th floor \u2014 flat 8007</div></div>\n      <div class=\"ldPol\" style=\"--r:-1.5deg\"><div class=\"pin\"></div><img alt=\"City skyline from the roof\" src=\"data:image/jpeg;base64,\"><div class=\"tag\"><b>EXHIBIT B-3</b>Roof \u2014 the city, from their ledge</div></div>\n    </div>\n  </div></div>\n  <div class=\"ldSec\"><div class=\"ldIn\">\n    <div class=\"ldEyebrow\">EXHIBIT C \u2014 PROPERTY MANIFEST</div>\n    <div class=\"ldMan\">\n      <div class=\"ldMc\"><h3>THE CODE</h3><p>A phone that won't stop ringing, and a number only one person would still remember to dial.</p></div>\n      <div class=\"ldMc\"><h3>THE MUSIC BOX</h3><p>Four brass chimes on a rooftop, wired to a cylinder that only plays her song in her order.</p></div>\n      <div class=\"ldMc\"><h3>THE SAFE</h3><p>A four-part key, assembled from pieces she hid in places only the two of them ever went.</p></div>\n    </div>\n  </div></div>\n  <div class=\"ldSec ldClose\"><div class=\"ldIn\">\n    <div class=\"ldStamp\">CASE CLOSED \u2014 YOUR CHOICE</div>\n    <h2>Two ways down.<br>One year to choose.</h2>\n    <div class=\"ldBtns\" style=\"justify-content:center\"><span class=\"ldBtn\" id=\"ldPlay2\">\u25b6 PLAY \u2014 FREE, IN THIS TAB</span></div>\n  </div></div>\n</div>\n\n<div class=\"screen\" id=\"title\">\n  <div class=\"rain\"></div>\n  <h1>NOIR</h1>\n  <div class=\"sub\">\"TRANSIT\" \u00b7 THE FULL GAME</div>\n  <p>A man searches a rain-soaked apartment building for his missing wife \u2014<br>\n  solving the puzzles of his own grief.<br><br>One year since Eileen. Two ways down.</p>\n  <div class=\"go\" id=\"startBtn\">BEGIN</div>\n  <div id=\"continueBtn\" class=\"hide\">CONTINUE</div>\n  <div class=\"keys\">WASD MOVE \u00b7 MOUSE LOOK \u00b7 E INTERACT \u00b7 F FLASHLIGHT \u00b7 TAB JOURNAL \u00b7 ` DEBUG<br>DESKTOP + MOUSE REQUIRED \u00b7 SOUND ON</div>\n</div>\n\n<div class=\"screen\" id=\"endScreen\" style=\"display:none;opacity:0\">\n  <h1 id=\"endTitle\" style=\"font-size:34px;letter-spacing:14px\">TRANSIT</h1>\n  <div class=\"sub\" id=\"endStats\"></div>\n  <p id=\"endBody\"></p>\n  <div class=\"go\" onclick=\"location.reload()\">AGAIN</div>\n</div>\n\n<div class=\"overlay\" id=\"pauseOverlay\"><div id=\"pauseBox\">\n  <div id=\"pauseHead\">\n    <h2 id=\"pauseTitle\">PAUSED</h2>\n    <div class=\"pausesub\" id=\"pauseSub\">3 save slots, stored locally in this browser.</div>\n  </div>\n  <div id=\"pauseScroll\">\n    <div class=\"slotsGrid\" id=\"slotsGrid\"></div>\n  </div>\n  <div class=\"pauseFoot\">\n    <div class=\"rowBtn\" id=\"pauseBack\">BACK TO TITLE</div>\n    <div class=\"rowBtn\" id=\"pauseResume\">RESUME</div>\n  </div>\n</div></div>\n\n<div id=\"fader\"></div>\n\n";
const STYLE_CSS = "\n  :root{\n    --paper:#d8d0bc; --ink:#22201a; --hud:#b8c4b0; --dim:#6d7568; --accent:#c8a070; --blood:#7a2a22;\n  }\n  *{margin:0;padding:0;box-sizing:border-box}\n  html,body{width:100%;height:100%;overflow:hidden;background:#000;font-family:\"Courier New\",monospace}\n  #c{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated;cursor:crosshair}\n\n  /* ---------- HUD ---------- */\n  #hud{position:absolute;inset:0;pointer-events:none;color:var(--hud);text-shadow:0 0 6px rgba(0,0,0,.9),1px 1px 0 #000}\n  #objective{position:absolute;top:14px;left:16px;font-size:13px;letter-spacing:1px;max-width:46ch;line-height:1.5}\n  #objective b{color:var(--accent);font-weight:normal}\n  #objective .tag{font-size:10px;color:var(--dim);letter-spacing:3px}\n  #prompt{position:absolute;left:50%;top:58%;transform:translateX(-50%);font-size:14px;letter-spacing:2px;opacity:0;transition:opacity .12s}\n  #prompt kbd{border:1px solid var(--hud);padding:1px 6px;margin-right:8px;border-radius:2px;font-size:12px}\n  #reticle{position:absolute;left:50%;top:50%;width:4px;height:4px;margin:-2px;background:rgba(200,200,190,.55);border-radius:50%}\n  #subtitle{position:absolute;bottom:120px;left:50%;transform:translateX(-50%);width:min(70ch,86vw);text-align:center;font-size:15px;line-height:1.6;color:#d7d2c2;font-style:italic}\n  #subtitle .who{font-style:normal;font-size:11px;letter-spacing:4px;color:var(--dim);display:block;margin-bottom:2px}\n  #battery{position:absolute;bottom:24px;left:20px;width:110px}\n  #battery .lbl{font-size:9px;letter-spacing:3px;color:var(--dim);margin-bottom:3px}\n  #battery .bar{height:5px;border:1px solid var(--dim);padding:1px}\n  #battery .fill{height:100%;background:var(--hud);width:100%;transition:width .3s}\n  #inv{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);display:flex;gap:6px}\n  .slot{width:46px;height:46px;border:1px solid rgba(140,150,135,.5);background:rgba(5,7,6,.55);display:flex;align-items:center;justify-content:center;flex-direction:column;font-size:8px;letter-spacing:1px;color:var(--dim);text-align:center;padding:2px}\n  .slot .ic{font-size:18px;line-height:1;filter:grayscale(.4) sepia(.3) brightness(.9)}\n  .slot.full{border-color:var(--accent);color:var(--hud)}\n  #journalHint{position:absolute;bottom:24px;right:20px;font-size:10px;letter-spacing:2px;color:var(--dim)}\n  #toast{position:absolute;top:14px;right:18px;font-size:12px;letter-spacing:1px;color:var(--accent);text-align:right;line-height:1.7}\n  .fadein{animation:fin .4s both}@keyframes fin{from{opacity:0;transform:translateY(-4px)}to{opacity:1}}\n\n  /* ---------- Overlays ---------- */\n  .overlay{position:absolute;inset:0;background:rgba(2,3,4,.82);display:none;align-items:center;justify-content:center;z-index:45;pointer-events:auto}\n  .overlay.show{display:flex}\n  .overlay button,.overlay .close{pointer-events:auto}\n\n  /* ---------- Save / Load ---------- */\n  #menuToggle{position:absolute;bottom:8px;right:110px;z-index:55;pointer-events:auto;font:10px \"Courier New\",monospace;letter-spacing:2px;color:#54606c;background:rgba(10,14,18,.55);border:1px solid #26303a;padding:4px 8px;cursor:pointer;user-select:none}\n  #menuToggle:hover{color:var(--accent);border-color:var(--accent)}\n  #pauseBox{width:min(74ch,92vw);max-height:86vh;background:rgba(8,9,10,.96);border:1px solid #2a2e28;box-shadow:0 0 80px rgba(0,0,0,.9);display:flex;flex-direction:column}\n  #pauseHead{padding:24px 38px 0}\n  #pauseBox h2{font-size:15px;letter-spacing:8px;color:var(--hud);font-weight:normal;margin-bottom:4px}\n  #pauseBox .pausesub{font-size:10px;letter-spacing:2px;color:var(--dim);margin-bottom:16px}\n  #pauseScroll{overflow:auto;padding:0 38px;flex:1 1 auto;min-height:0}\n  .slotsGrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;margin-bottom:16px}\n  .saveSlot{border:1px solid #363c34;background:rgba(20,22,18,.5);padding:8px;display:flex;flex-direction:column;gap:6px}\n  .saveSlot.empty{align-items:center;justify-content:center;min-height:110px;color:var(--dim);font-size:10px;letter-spacing:2px}\n  .saveThumb{width:100%;aspect-ratio:4/3;object-fit:cover;background:#0a0b0c;border:1px solid #2a2e28;filter:saturate(.8) contrast(1.05)}\n  .saveMeta{font-size:10px;letter-spacing:1px;color:var(--dim);line-height:1.6}\n  .saveMeta b{color:var(--hud);font-weight:normal}\n  .saveBtns{display:flex;gap:6px;flex-wrap:wrap}\n  .saveBtns button,#pauseBox .rowBtn{font:10px \"Courier New\",monospace;letter-spacing:2px;color:var(--hud);background:transparent;border:1px solid #4a524a;padding:6px 10px;cursor:pointer}\n  .saveBtns button:hover,#pauseBox .rowBtn:hover{color:#0a0b0c;background:var(--accent);border-color:var(--accent)}\n  .saveBtns button.danger:hover{background:var(--blood);border-color:var(--blood);color:#f0e8e0}\n  #pauseBox .pauseFoot{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #2a2e28;padding:16px 38px;flex:0 0 auto}\n  #pauseBox .pauseFoot .rowBtn{padding:9px 20px}\n  #continueBtn{margin-top:14px;border:1px solid #3a4238;padding:10px 34px;font-size:11px;letter-spacing:4px;cursor:pointer;color:var(--dim)}\n  #continueBtn:hover{color:var(--hud);border-color:var(--hud)}\n  #continueBtn.hide{display:none}\n  .paper{background:var(--paper);color:var(--ink);width:min(58ch,88vw);max-height:80vh;overflow:auto;padding:38px 42px;box-shadow:0 0 60px rgba(0,0,0,.9), inset 0 0 60px rgba(90,70,40,.25);transform:rotate(-.6deg);font-size:15px;line-height:1.8;position:relative}\n  .paper::before{content:\"\";position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent 0 26px,rgba(60,40,20,.06) 26px 27px);pointer-events:none}\n  .paper h3{font-size:11px;letter-spacing:4px;color:#6a5a3a;margin-bottom:16px;font-weight:normal}\n  .paper .digits{font-size:30px;letter-spacing:8px;text-align:center;margin:18px 0;color:#3a2c18}\n  .paper .close{position:absolute;top:10px;right:14px;font-size:11px;letter-spacing:2px;color:#7a6a4a;cursor:pointer}\n  .paper em{color:#5a4426}\n\n  /* dial pad */\n  #dialBox{background:#101210;border:1px solid #3a423a;padding:26px;width:280px;color:var(--hud);text-align:center;box-shadow:0 0 80px #000}\n  #dialBox h3{font-size:10px;letter-spacing:4px;color:var(--dim);margin-bottom:12px}\n  #dialDisp{font-size:22px;letter-spacing:5px;height:34px;border-bottom:1px solid #3a423a;margin-bottom:16px;color:#d8e0d0}\n  #dialPad{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:14px}\n  #dialPad button, .dbtn{background:#1a1e1a;border:1px solid #3a423a;color:var(--hud);font-family:inherit;font-size:16px;padding:10px 0;cursor:pointer}\n  #dialPad button:hover,.dbtn:hover{background:#2a2e28;border-color:var(--accent)}\n  #dialRow{display:flex;gap:8px}\n  #dialRow .dbtn{flex:1;font-size:11px;letter-spacing:2px;padding:10px 0}\n\n  /* journal */\n  #journalBox{background:#0e100e;border:1px solid #3a423a;width:min(78ch,90vw);max-height:80vh;display:flex;color:var(--hud);box-shadow:0 0 80px #000}\n  #jList{width:220px;border-right:1px solid #2a2e2a;overflow:auto}\n  #jList .jt{padding:12px 14px;font-size:11px;letter-spacing:1px;cursor:pointer;border-bottom:1px solid #1a1e1a;color:var(--dim)}\n  #jList .jt.got{color:var(--hud)} #jList .jt.sel{background:#1a1e18;color:var(--accent)}\n  #jRead{flex:1;padding:26px;font-size:13px;line-height:1.9;overflow:auto;font-style:italic;color:#c9c4b2;white-space:pre-wrap}\n  #jHead{padding:10px 14px;font-size:10px;letter-spacing:4px;color:var(--dim);border-bottom:1px solid #2a2e2a}\n\n  /* screens */\n\n  /* ---------- LANDING (case-file front page, shown before the title) ---------- */\n  #landing{position:absolute;inset:0;z-index:80;background:#0a0b0d;color:#b8c4b0;overflow-y:auto;overflow-x:hidden;\n    font-family:\"Courier New\",monospace}\n  #landing.gone{display:none}\n  #landing ::selection{background:#c8935a;color:#0a0b0d}\n  .ldGrain{position:fixed;inset:0;pointer-events:none;opacity:.05;mix-blend-mode:overlay;\n    background-image:radial-gradient(circle,#fff 1px,transparent 1px);background-size:3px 3px}\n  .ldRec{position:absolute;top:16px;right:18px;font-size:11px;letter-spacing:2px;color:#c85050;display:flex;gap:7px;align-items:center}\n  .ldRec .d{width:7px;height:7px;border-radius:50%;background:#e04040;animation:ldBlink 1.6s steps(1) infinite}\n  @keyframes ldBlink{0%,49%{opacity:1}50%,100%{opacity:.15}}\n  .ldHero{min-height:100vh;display:flex;flex-direction:column;justify-content:center;position:relative;padding:90px 26px 60px;\n    background:linear-gradient(180deg,rgba(6,7,8,.4),rgba(6,7,8,.88) 68%,#0a0b0d),var(--ldhero) center 30%/cover}\n  .ldIn{max-width:980px;margin:0 auto;width:100%}\n  .ldCase{font-size:12px;letter-spacing:4px;color:#6d7568;margin-bottom:24px}\n  .ldCase b{color:#e8b060;font-weight:normal}\n  .ldWord{font-size:clamp(60px,13vw,150px);letter-spacing:.14em;font-weight:bold;line-height:.92;color:#e8e4d4;\n    text-shadow:0 0 40px rgba(0,0,0,.9)}\n  .ldSub{font-size:clamp(13px,2vw,17px);letter-spacing:.5em;color:#c8935a;margin:14px 0 30px;padding-left:.5em}\n  .ldLog{max-width:52ch;font-size:14px;line-height:1.85;font-style:italic;margin-bottom:38px}\n  .ldLog b{color:#d9d2bc;font-style:normal}\n  .ldBtns{display:flex;gap:14px;flex-wrap:wrap}\n  .ldBtn{display:inline-block;border:1px solid #c8935a;color:#e8b060;padding:15px 30px;font-size:12px;\n    letter-spacing:3px;cursor:pointer;background:rgba(10,11,13,.4);user-select:none}\n  .ldBtn:hover{background:#c8935a;color:#0a0b0d}\n  .ldBtn.ghost{border-color:#464e46;color:#6d7568}\n  .ldBtn.ghost:hover{border-color:#b8c4b0;color:#b8c4b0;background:transparent}\n  .ldSec{max-width:980px;margin:0 auto;padding:90px 26px;border-top:1px solid #262b26}\n  .ldEyebrow{font-size:11px;letter-spacing:5px;color:#6d7568;margin-bottom:20px;display:flex;align-items:center;gap:12px}\n  .ldEyebrow::before{content:\"\";width:26px;height:1px;background:#464e46}\n  .ldTyped{max-width:64ch;font-size:14px;line-height:2;color:#a8b0a0}\n  .ldTyped b{color:#d9d2bc}\n  .ldRedact{background:#1c1e1a;color:transparent;padding:0 6px;user-select:none}\n  .ldStats{display:flex;gap:32px;flex-wrap:wrap;margin-top:40px;padding-top:28px;border-top:1px dashed #262b26}\n  .ldStats div{font-size:10px;letter-spacing:2px;color:#6d7568}\n  .ldStats b{display:block;font-size:19px;color:#d9d2bc;font-weight:normal;margin-top:5px}\n  .ldBoard{background:repeating-linear-gradient(90deg,#17140f 0 2px,#1a1712 2px 4px);border:1px solid #2a2620;\n    padding:44px 26px 34px;margin-top:36px;display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:30px 22px}\n  .ldPol{background:#e8e2ce;padding:9px 9px 38px;position:relative;box-shadow:0 10px 24px rgba(0,0,0,.55);\n    transform:rotate(var(--r,0deg));transition:transform .25s}\n  .ldPol:hover{transform:rotate(0) scale(1.04)}\n  .ldPol img{width:100%;aspect-ratio:4/3;object-fit:cover;display:block;filter:saturate(.82) contrast(1.08)}\n  .ldPol .pin{position:absolute;top:-8px;left:50%;transform:translateX(-50%);width:15px;height:15px;border-radius:50%;\n    background:radial-gradient(circle at 35% 30%,#e8746a,#8a2a22);box-shadow:0 3px 5px rgba(0,0,0,.6)}\n  .ldPol .tag{position:absolute;bottom:9px;left:9px;right:9px;font-size:10px;color:#2a2620}\n  .ldPol .tag b{display:block;font-size:8.5px;letter-spacing:2px;color:#8a3226;margin-bottom:2px}\n  .ldMan{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#262b26;border:1px solid #262b26;margin-top:36px}\n  @media(max-width:760px){.ldMan{grid-template-columns:1fr}}\n  .ldMc{background:#0a0b0d;padding:22px 20px}\n  .ldMc h3{font-size:12px;letter-spacing:2px;color:#d9d2bc;font-weight:normal;margin-bottom:9px}\n  .ldMc p{font-size:12px;line-height:1.75;color:#6d7568}\n  .ldClose{text-align:center;padding-bottom:70px}\n  .ldStamp{display:inline-block;border:3px solid #8a3226;color:#8a3226;font-size:12px;letter-spacing:5px;\n    padding:9px 20px;transform:rotate(-4deg);margin-bottom:30px;opacity:.85}\n  .ldClose h2{font-size:clamp(26px,4.6vw,46px);letter-spacing:.08em;color:#d9d2bc;margin-bottom:26px}\n\n  .screen{position:absolute;inset:0;background:#000;display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:40;color:#cfcabb;text-align:center;transition:opacity 1.4s}\n  .screen h1{font-size:52px;letter-spacing:22px;font-weight:normal;color:#d8d2c2;margin-bottom:8px;text-indent:22px}\n  .screen .sub{font-size:12px;letter-spacing:6px;color:#6a7264;margin-bottom:44px}\n  .screen p{font-size:13px;line-height:2;max-width:56ch;color:#8b877a;font-style:italic}\n  .screen .go{margin-top:44px;border:1px solid #4a524a;padding:12px 34px;font-size:12px;letter-spacing:4px;cursor:pointer;color:var(--hud)}\n  .screen .go:hover{border-color:var(--accent);color:var(--accent)}\n  .screen .keys{margin-top:28px;font-size:10px;letter-spacing:2px;color:#565e52;line-height:2.2}\n  #fader{position:absolute;inset:0;background:#000;pointer-events:none;z-index:30;opacity:1;transition:opacity 2.5s}\n  .rain{position:absolute;inset:0;pointer-events:none;opacity:.05;background:repeating-linear-gradient(78deg,transparent 0 2px,#9ab 2px 3px);animation:rn .4s linear infinite}\n  @keyframes rn{to{background-position:60px 200px}}\n/* ---- DEBUG MENU ---- */\n#dbgToggle{position:absolute;bottom:8px;right:10px;z-index:55;pointer-events:auto;font:10px \"Courier New\",monospace;letter-spacing:2px;color:#54606c;background:rgba(10,14,18,.55);border:1px solid #26303a;padding:4px 8px;cursor:pointer;user-select:none}\n#dbgToggle:hover{color:#e8b060;border-color:#e8b060}\n#dbgPanel{position:absolute;top:10px;right:10px;width:275px;max-height:calc(100vh - 20px);overflow-y:auto;z-index:60;pointer-events:auto;\n  background:rgba(6,8,10,.92);border:1px solid #3a4450;padding:10px 12px;z-index:40;display:none;\n  font:12px \"Courier New\",monospace;color:#c8d0d8}\n#dbgPanel.show{display:block}\n#dbgPanel h3{margin:0 0 8px;font-size:13px;color:#e8b060;letter-spacing:2px}\n#dbgPanel h4{margin:10px 0 4px;font-size:11px;color:#7a92a8;letter-spacing:1px;border-bottom:1px solid #26303a;padding-bottom:2px}\n#dbgPanel button{background:#141a20;border:1px solid #3a4450;color:#c8d0d8;font:11px \"Courier New\",monospace;\n  padding:4px 7px;margin:2px 3px 2px 0;cursor:pointer}\n#dbgPanel button:hover{background:#22303c;border-color:#e8b060;color:#fff}\n#dbgPanel button.on{background:#2a4030;border-color:#70c080;color:#b0f0c0}\n#dbgPanel label{display:flex;align-items:center;gap:6px;margin:3px 0}\n#dbgPanel input[type=range]{flex:1;accent-color:#e8b060}\n#dbgHud{position:absolute;top:10px;left:10px;z-index:39;display:none;background:rgba(4,6,8,.7);\n  border:1px solid #26303a;padding:6px 9px;font:11px \"Courier New\",monospace;color:#8fe0a0;white-space:pre;line-height:1.55}\n";

// Set NEXT_PUBLIC_BASE_PATH (e.g. "/Noir-Transit") when hosting under a subpath.
const BASE_PATH = process.env.NEXT_PUBLIC_BASE_PATH || "";

function loadScript(src) {
  return new Promise((resolve, reject) => {
    const s = document.createElement("script");
    s.src = src;
    s.async = false; // preserve execution order
    s.onload = () => resolve();
    s.onerror = () => reject(new Error("Failed to load " + src));
    document.body.appendChild(s);
  });
}

export default function NoirGame() {
  const containerRef = useRef(null);
  const bootedRef = useRef(false);

  useEffect(() => {
    // Guard against double-invocation (React StrictMode dev double-effect,
    // or remounts) — this engine is a singleton full-page WebGL app with no
    // teardown path, so it must only ever boot once per real page load.
    if (bootedRef.current) return;
    if (typeof window !== "undefined" && window.__noirBooted) return;
    bootedRef.current = true;
    if (typeof window !== "undefined") window.__noirBooted = true;

    let cancelled = false;
    (async () => {
      try {
        await loadScript(BASE_PATH + "/game/three.min.js");
        if (cancelled) return;
        await loadScript(BASE_PATH + "/game/engine.js");
      } catch (err) {
        console.error("NOIR engine failed to load:", err);
      }
    })();

    return () => { cancelled = true; };
  }, []);

  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: STYLE_CSS }} />
      <style dangerouslySetInnerHTML={{ __html: `
        html[data-zone="metro"] #battery,
        html[data-zone="metro"] #inv,
        html[data-zone="metro"] #journalHint,
        html[data-zone="metro"] #menuToggle,
        html[data-zone="metro"] #dbgToggle {
          text-shadow: 0 0 7px #000, 0 1px 0 #000;
          filter: drop-shadow(0 1px 2px rgba(0,0,0,.9));
        }
        html[data-zone="metro"] #battery::before,
        html[data-zone="metro"] #inv::before {
          content: "";
          position: absolute;
          inset: -6px -8px;
          background: rgba(3,6,8,.28);
          z-index: -1;
        }
        html[data-zone="metro"] #prompt {
          color: #e0dfca;
          text-shadow: 0 0 8px #000, 0 1px 0 #000;
        }
      ` }} />
      <div ref={containerRef} dangerouslySetInnerHTML={{ __html: MARKUP_HTML }} />
    </>
  );
}
